
import constant from './constant/constant';

export function storeDataLocalStorage(key: string, value: string) {
  localStorage.setItem(key, value)
}

export function storeObjectLocalStorage<T>(key: string, value: T) {
  localStorage.setItem(key, JSON.stringify(value))
}

export function getDataFromLocalStorage(key: string) {
  let value = null;
  try {
    value = localStorage.getItem(key)
  }
  catch (err) {
    console.error("err in getDataFromLocalStorage")
  }
  return value
}

export function getObjectFromLocalStorage(key: string) {
  let value = null;
  try {
    const data = localStorage.getItem(key);
    value = data ? JSON.parse(data) : null;
  }
  catch (err) {
    console.error("err in getObjectFromLocalData")
  }
  return value
}

export function removelocalData(key: string) {
  localStorage.removeItem(key)
}

// for sign
export async function signout() {
  for (let i of Object.keys(constant) as Array<keyof typeof constant>) {
    removelocalData(constant[i])
  }
}

export function emailValidate(str: string) {
  try {
    return /\S+@\S+\.\S+/.test(str);
  }
  catch (err) {

  }
  return false
}

export function digitValidate(str: string) {
  try {
    return /^[0-9]?$/.test(str);
  }
  catch (err) {

  }
  return false
}

export function randomDigitsID(length: number) {
  const max = 10 ** length;
  const n = Math.floor(Math.random() * max);
  return String(n).padStart(length, '0');
}

export function isValidHttpUrlRegex(string: string): boolean {
    try {
        if (!string) {
            return false
        }
        const pattern = new RegExp(
            '^' +
            // 1. Protocol (http or https required)
            'https?:\\/\\/' +
            // 2. Domain name (e.g., google.com) OR IP address (v4)
            '((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.)+[a-z]{2,}|((\\d{1,3}\\.){3}\\d{1,3}))' +
            // 3. Optional port number
            '(\\:\\d+)?' +
            // 4. Optional path
            '(\\/[-a-z\\d%_.~+]*)*' +
            // 5. Optional query string
            '(\\?[;&a-z\\d%_.~+=-]*)?' +
            // 6. Optional fragment/anchor locator
            '(\\#[-a-z\\d_]*)?$',
            'i' // Case-insensitive flag
        );

        return pattern.test(string);
    }
    catch (err) {
        return false
    }
}