import Moment from "moment";
import React, { useEffect, useState } from "react";
import { toast } from "react-toastify";
import { useUpgradeModal } from "../components/DashboardLayout";
import LinkAnalyticsModal from "../components/LinkAnalyticsModal";
import QRCodeModal from "../components/QRCodeModal";
import Messeges from "../constant/Messeges";
import { API_BASE, DateFormate, PlanNameEnum, PlanTypeEnum } from "../constant/constant";
import { createLink, deleteLink, fetchLinks, updateLink } from "../store/slices/linkSlice";
import { useAppDispatch, useAppSelector } from "../store/store";
import { formErrorT } from "../types";
import { isValidHttpUrlRegex } from "../utility";

const Links: React.FC = () => {
  const dispatch = useAppDispatch();
  const { openUpgradeModal } = useUpgradeModal();
  const { links, loading } = useAppSelector((state) => state.links);
  const { user } = useAppSelector((state) => state.auth);

  const [originalUrl, setOriginalUrl] = useState<string>("");
  const [customCode, setCustomCode] = useState<string>("");
  const [tagsInput, setTagsInput] = useState<string>("");
  const [expiresAtInput, setExpiresAtInput] = useState<string>("");
  const [search, setSearch] = useState<string>("");
  const [formError, setFormError] = useState<formErrorT>({});
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [qrTarget, setQrTarget] = useState<{ url: string; code: string } | null>(null);
  const [analyticsId, setAnalyticsId] = useState<string | null>(null);

  const isFreePlan = user?.plan === PlanTypeEnum.Free;
  const isPremium = user?.plan === PlanTypeEnum.premium_month;

  useEffect(() => {
    dispatch(fetchLinks());
  }, [dispatch]);

  const validateInput = () => {
    let errors: formErrorT = {};
    let valid = true;

    if (!originalUrl.trim()) {
      errors.originalUrl = Messeges.v_URL;
      valid = false;
    }
    else if (!isValidHttpUrlRegex(originalUrl?.trim())) {
      errors.originalUrl = Messeges.v_URL1;
      valid = false;
    }

    setFormError(errors);
    return valid;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateInput()) return;
    const tags = tagsInput
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean)
      .slice(0, 5);

    const expiresAtInputTemp = new Date(expiresAtInput);
    dispatch(createLink({
      originalUrl: originalUrl?.trim(),
      customCode: customCode?.trim() || undefined,
      tags,
      expiresAt: Moment
        .utc(`${expiresAtInputTemp.getFullYear()}/${expiresAtInputTemp.getMonth() + 1}/${expiresAtInputTemp.getDate()}`)
        .add(23, "hour")
        .add(59, "minute")
        .add(59, "second")
        .toISOString()
    })
    ).then(
      (res: any) => {
        if (!res.error) {
          setOriginalUrl("");
          setCustomCode("");
          setTagsInput("");
          setExpiresAtInput("");
          toast.success(Messeges.m_link_created);
        }
        else if (res?.payload?.statuscode === 403) {
          toast.error(res.payload.message || res.payload);
          openUpgradeModal();
        }
        else if (res?.payload?.statuscode === 409) {
          toast.error(Messeges.m_sort_code_exists);
        }
        else if (res?.payload?.statuscode === 400) {
          toast.error(res?.payload?.message || Messeges.m_createlink);
        }
        else {
          toast.error(Messeges.m_createlink);
        }
      }
    );
  };

  const handleDelete = (id: string) => {
    if (!window.confirm("Delete this short link? This can't be undone.")) return;
    dispatch(deleteLink(id)).then((res: any) => {
      if (!res.error) toast.success(Messeges.m_link_deleted);
    });
  };

  const handleToggleActive = (id: string, isActive: boolean) => {
    dispatch(updateLink({ id, isActive: !isActive }));
  };

  const handleCopy = (id: string, shortCode: string) => {
    navigator.clipboard.writeText(`${API_BASE}/r/${shortCode}`);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 1500);
  };

  const filteredLinks = links.filter(
    (link) =>
      link.originalUrl.toLowerCase().includes(search.toLowerCase()) ||
      link.shortCode.toLowerCase().includes(search.toLowerCase()) ||
      link.tags.some((t) => t.toLowerCase().includes(search.toLowerCase()))
  );

  console.log(PlanNameEnum[user?.plan], user?.plan)

  return (
    <div>
      <div className="d-flex flex-wrap align-items-center justify-content-between mb-4 gap-2">
        <div>
          <h3 className="fw-bold mb-1">My Links</h3>
          <p className="text-muted mb-0">Create, organize, and track every short link you own.</p>
        </div>
      </div>

      {/* Create form */}
      <div className="card border-0 shadow-sm rounded-4-custom mb-4">
        <div className="card-body p-4">
          <h6 className="fw-bold mb-3">Create a new short link</h6>
          <form onSubmit={handleSubmit} className="row g-3">
            <div className="col-md-12">
              <label className="form-label small fw-semibold">Destination Link</label>
              <input
                type="url"
                className="form-control"
                placeholder="https://example.com/very/long/link"
                value={originalUrl}
                onChange={(e) => setOriginalUrl(e.target.value)}
              />
              <div className="text-danger">
                {formError?.originalUrl}
              </div>
            </div>
            <div className="col-md-4">
              <label className="form-label small fw-semibold d-flex align-items-center gap-1">
                Custom code
                {isFreePlan && (
                  <span className="badge bg-warning text-dark" style={{ fontSize: 10 }}>
                    {PlanNameEnum[PlanTypeEnum.standard_month]}
                  </span>
                )}
              </label>
              <input
                type="text"
                className="form-control"
                placeholder={isFreePlan ? "Upgrade to unlock" : "my-link"}
                value={customCode}
                maxLength={20}
                onChange={(e) => setCustomCode(e.target.value)}
                disabled={isFreePlan}
              />
              <div className="text-danger">
                {formError?.customCode}
              </div>
            </div>
            <div className="col-md-4">
              <label className="form-label small fw-semibold d-flex align-items-center gap-1">Tags (comma separated)
                {!isPremium && (
                  <span className="badge bg-warning text-dark" style={{ fontSize: 10 }}>
                    {PlanNameEnum[PlanTypeEnum.premium_month]}
                  </span>
                )}
              </label>
              <input
                type="text"
                className="form-control"
                placeholder="marketing, launch"
                value={tagsInput}
                disabled={!isPremium}
                onChange={(e) => setTagsInput(e.target.value)}
              />
              <div className="text-danger">
                {formError?.tagsInput}
              </div>
            </div>
            <div className="col-md-4">
              <label className="form-label small fw-semibold d-flex align-items-center gap-1">Expire At
                {!isPremium && (
                  <span className="badge bg-warning text-dark" style={{ fontSize: 10 }}>
                    {PlanNameEnum[PlanTypeEnum.premium_month]}
                  </span>
                )}
              </label>
              <input
                type="date"
                className="form-control"
                placeholder="marketing, launch"
                value={expiresAtInput}
                disabled={!isPremium}
                min={new Date().toISOString().split("T")[0]}
                onChange={(e) => setExpiresAtInput(e.target.value)}
              />
              <div className="text-danger">
                {formError?.expiresAtInput}
              </div>
            </div>
            <div className="col-12">
              <button className="btn btn-primary" type="submit" disabled={loading}>
                {loading ? "Creating..." : "Create short link"}
              </button>
            </div>
          </form>
        </div>
      </div>

      {/* Table */}
      <div className="card border-0 shadow-sm rounded-4-custom">
        <div className="card-body p-4">
          <div className="d-flex flex-wrap justify-content-between align-items-center mb-3 gap-2">
            <h6 className="fw-bold mb-0">All links ({filteredLinks.length})</h6>
            <div className="input-group" style={{ maxWidth: 280 }}>
              <span className="input-group-text bg-white border-end-0">
                <i className="bi bi-search text-muted"></i>
              </span>
              <input
                type="text"
                className="form-control border-start-0"
                placeholder="Search links or tags..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
          </div>

          {filteredLinks.length === 0 ? (
            <p className="text-muted small mb-0">No links match your search yet.</p>
          ) : (
            <div className="table-responsive">
              <table className="table table-fixed7col table-col7 align-middle">
                <thead>
                  <tr className="text-muted small">
                    <th>Short link</th>
                    <th>Destination</th>
                    <th>Tags</th>
                    <th>Expire At</th>
                    <th className="text-center">Clicks</th>
                    <th className="text-center">Status</th>
                    <th className="text-end">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredLinks.map((link) => (
                    <tr key={link._id}>
                      <td>
                        <a
                          href={`${API_BASE}/r/${link.shortCode}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="fw-semibold"
                        >
                          /r/{link.shortCode}
                        </a>
                      </td>
                      <td className="text-truncate">
                        {link.originalUrl}
                      </td>
                      <td>
                        {link.tags.map((tag) => (
                          <span key={tag} className="badge bg-light text-dark border me-1 mb-1">
                            {tag}
                          </span>
                        ))}
                      </td>
                      <td className="text-truncate">
                        {link.expiresAt ? Moment.utc(link.expiresAt).format(DateFormate.YYYYMMMDDDash) : "-"}
                      </td>
                      <td className="text-center">
                        <span className="badge bg-secondary">{link.clicks}</span>
                      </td>
                      <td className="text-center">
                        <div className="form-check form-switch d-flex justify-content-center">
                          <input
                            className="form-check-input"
                            type="checkbox"
                            checked={link.isActive}
                            onChange={() => handleToggleActive(link._id, link.isActive)}
                            title={link.isActive ? "Active" : "Disabled"}
                          />
                        </div>
                      </td>
                      <td className="text-end">
                        <div className="btn-group">
                          <button
                            className="btn btn-sm btn-outline-secondary"
                            title="Copy"
                            onClick={() => handleCopy(link._id, link.shortCode)}
                          >
                            <i className={`bi ${copiedId === link._id ? "bi-check-lg" : "bi-clipboard"}`}></i>
                          </button>
                          <button
                            className="btn btn-sm btn-outline-secondary"
                            title="QR code"
                            onClick={() =>
                              setQrTarget({ url: `${API_BASE}/r/${link.shortCode}`, code: link.shortCode })
                            }
                          >
                            <i className="bi bi-qr-code"></i>
                          </button>
                          <button
                            className="btn btn-sm btn-outline-secondary"
                            title="Analytics"
                            disabled={link.clicks === 0}
                            onClick={() => setAnalyticsId(link._id)}
                          >
                            <i className="bi bi-graph-up"></i>
                          </button>
                          <button
                            className="btn btn-sm btn-outline-danger"
                            title="Delete"
                            onClick={() => handleDelete(link._id)}
                          >
                            <i className="bi bi-trash"></i>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      <QRCodeModal
        show={!!qrTarget}
        onClose={() => setQrTarget(null)}
        url={qrTarget?.url || ""}
        shortCode={qrTarget?.code || ""}
      />

      <LinkAnalyticsModal show={!!analyticsId} onClose={() => setAnalyticsId(null)} linkId={analyticsId} />
    </div>
  );
};

export default Links;
