import React from "react";
import { useNavigate } from "react-router-dom";
import { logout } from "../store/slices/authSlice";
import { useAppDispatch, useAppSelector } from "../store/store";

interface TopbarProps {
  title: string;
  onMenuClick: () => void;
}

const Topbar: React.FC<TopbarProps> = ({ title, onMenuClick }) => {
  const { user } = useAppSelector((state) => state.auth);
  const dispatch = useAppDispatch();
  const navigate = useNavigate();

  const initials = ((user?.firstname || user?.lastname) ? (`${user?.firstname} ${user?.lastname}`) : "U")
    .split(" ")
    .map((n) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();

  const handleLogout = () => {
    dispatch(logout());
    navigate("/login");
  };

  return (
    <header className="bg-white border-bottom px-3 px-lg-4 py-3 d-flex align-items-center justify-content-between sticky-top">
      <div className="d-flex align-items-center gap-3">
        <button className="btn btn-light d-lg-none" onClick={onMenuClick}>
          <i className="bi bi-list fs-5"></i>
        </button>
        <h5 className="mb-0 fw-bold">{title}</h5>
      </div>

      <div className="dropdown">
        <button
          className="btn btn-light d-flex align-items-center gap-2 rounded-pill px-2 py-1"
          data-bs-toggle="dropdown"
          aria-expanded="false"
        >
          <div
            className="d-flex align-items-center justify-content-center rounded-circle bg-primary text-white fw-semibold"
            style={{ width: 32, height: 32, fontSize: 13 }}
          >
            {initials}
          </div>
          <span className="d-none d-sm-inline small fw-semibold">{(user?.firstname || user?.lastname) ? (`${user?.firstname} ${user?.lastname}`) : "U"}</span>
          <i className="bi bi-chevron-down small"></i>
        </button>
        <ul className="dropdown-menu dropdown-menu-end shadow-sm">
          {/* <li>
            <span className="dropdown-item-text small text-muted">{user?.email}</span>
          </li> 
          <li>
            <hr className="dropdown-divider" />
          </li> */}
          <li>
            <button className="dropdown-item" onClick={() => navigate("/dashboard/settings")}>
              <i className="bi bi-gear me-2"></i>Settings
            </button>
          </li>
          <li>
            <button className="dropdown-item text-danger" onClick={handleLogout}>
              <i className="bi bi-box-arrow-right me-2"></i>Logout
            </button>
          </li>
        </ul>
      </div>
    </header>
  );
};

export default Topbar;
