import axios, { AxiosResponse } from "axios";
import Path from "../api.json";

const api = axios.create();

export function GetData(authToken: string | null, url: string):
  Promise<AxiosResponse> {
  return api.get(`${Path.baseURL}/${url}`, {
    headers: {
      Authorization: authToken ? `Bearer ${authToken}` : undefined,
      "Content-Type": "application/json"
    }
  })
}

export function PostData<T>(authToken: string | null, postData: T, url: string):
  Promise<AxiosResponse> {
  return api.post(`${Path.baseURL}/${url}`,
    postData,
    {
      headers: {
        Authorization: authToken ? `Bearer ${authToken}` : undefined,
        "Content-Type": "application/json"
      }
    })
}

export function PUTData<T>(authToken: string | null, postData: T, url: string):
  Promise<AxiosResponse> {
  return api.put(`${Path.baseURL}/${url}`, postData,
    {
      headers: {
        Authorization: authToken ? `Bearer ${authToken}` : undefined,
        "Content-Type": "application/json"
      }
    })
}

export function DeleteData<T>(authToken: string | null, postData: T, url: string):
  Promise<AxiosResponse> {
  return api.delete(`${Path.baseURL}/${url}`,
    {
      data: postData,
      headers: {
        Authorization: authToken ? `Bearer ${authToken}` : undefined,
        "Content-Type": "application/json"
      }
    })
}